const defaultFollowInterval = 2 * time.Second

// InEditMode keeps command mode out while a field has the keyboard: the search
// box, or the go-to-line prompt.
func (m Model) InEditMode() bool { return m.bar.InEditMode() || m.gotoActive }

// FilterBarVisible tells the router to close the viewport border into the bar
// (Rule 136).
func (m Model) FilterBarVisible() bool {
	// Every display but the tree is text, and the search belongs to all of
	// them: a rendered Markdown is searched on what it shows, which is the only
	// answer that agrees with the screen.
	//
	// The go-to-line prompt takes the same slot, so it closes the border the
	// same way — and the footer stands at the same height whether the prompt
	// opened over an active search or over nothing.
	return (m.bar.IsVisible() || m.gotoActive) && m.display != displayTree
}

func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.resize(msg.Width, msg.Height)
		return m, nil

	case tea.KeyPressMsg:
		return m.handleKeyMsg(msg)

	case tea.PasteMsg:
		return m.handlePaste(msg)

	case DocumentLoadedMsg:
		return m.handleDocumentLoaded(msg)

	case PagerExitMsg:
		return m.handlePagerExit(msg)

	case followTickMsg:
		return m.handleFollowTick(msg)

	case ContentCopiedMsg:
		return m.handleContentCopied(msg)

	case IDEOpenedMsg:
		return m.handleIDEOpened(msg)

	case jobs.FrameMsg:
		m.footer.SetBlinkPhase(msg.Blink)
		return m, nil
	}

	m.footer.Handle(msg)
	return m, nil
}

// resize lays out whichever half is on screen. Both are sized, not just the
// active one: a `f` between two window sizes would otherwise show a pane laid
// out for the previous width.
func (m *Model) resize(width, height int) {
	m.width = width
	m.height = height

	m.tree.Resize(width, height)

	m.textViewport.SetWidth(width)
	m.textViewport.SetHeight(max(height, 1))
	m.bar.Resize(width)
	m.rebuildText() // the wrap and the padding both depend on the width
}

